('127.47.d.10.B',4,'Analyzing all sides of an issue means:','["studying supporting and opposing evidence", "hearing one side", "ignoring critics", "avoiding data"]'::jsonb,0,'Fair analysis.','original'),
('127.47.d.10.B',4,'Understanding why people disagree helps a communicator to:','["insult them", "address concerns effectively", "avoid them", "dismiss them"]'::jsonb,1,'Empathy improves persuasion.','original'),
('127.47.d.10.C',4,'An advocacy plan should address:','["no one", "only critics", "both supporting and opposing arguments", "only supporters"]'::jsonb,2,'Preparation includes counterpoints.','original'),
('127.47.d.10.C',4,'An advocacy communication plan includes the audience, message and:','["gossip", "jokes", "secrecy", "delivery channels"]'::jsonb,3,'Plans define how to reach people.','original'),
('127.47.d.10.D',3,'Presenting an advocacy plan to an audience requires:','["clear speaking and organized visuals", "vague claims", "no preparation", "reading silently"]'::jsonb,0,'Delivery matters.','original'),
('127.47.d.10.D',3,'Ending an advocacy presentation with a call to action:','["confuses them", "tells the audience what to do next", "ignores them", "ends the issue"]'::jsonb,1,'Calls to action drive response.','original'),
('127.47.d.11.A',2,'Newspapers, radio and television are:','["farm tools", "soil types", "media outlets", "crops"]'::jsonb,2,'Outlets deliver information.','original'),
('127.47.d.11.A',3,'A modern media outlet that did not exist 50 years ago is:','["a radio", "a newspaper", "a magazine", "a podcast"]'::jsonb,3,'Digital media is newer.','original'),
('127.47.d.11.B',3,'A good agricultural article starts with:','["a strong lead that hooks readers", "a long background", "a conclusion", "random facts"]'::jsonb,0,'Leads grab attention.','original'),
('127.47.d.11.B',3,'Before publishing an article, a writer should:','["guess", "check facts and sources", "skip edits", "hide sources"]'::jsonb,1,'Accuracy is essential.','original'),
('127.47.d.11.C',3,'A radio script is written to be:','["unspoken", "read silently", "heard rather than read", "only visual"]'::jsonb,2,'Audio scripts use spoken style.','original'),
('127.47.d.11.C',3,'A podcast script should have:','["only ads", "no structure", "only music", "a clear intro, content and wrap-up"]'::jsonb,3,'Structure helps listeners.','original'),
('127.47.d.11.D',3,'A video script pairs narration with:','["visual cues", "silence only", "blank pages", "unrelated text"]'::jsonb,0,'Video combines audio and visuals.','original'),
('127.47.d.11.D',3,'A storyboard is used to:','["count cattle", "plan scenes for a video", "weigh crops", "print money"]'::jsonb,1,'It sequences visuals.','original'),
('127.47.d.11.E',3,'To critique a media platform, evaluate its:','["paint color", "staff birthdays", "reach, credibility and audience", "building"]'::jsonb,2,'Critique uses criteria.','original'),
('127.47.d.11.E',3,'Comparing a podcast to a newspaper shows differences in:','["tractor models", "geography only", "rainfall", "format and audience"]'::jsonb,3,'Platforms differ.','original'),
('127.47.d.11.F',3,'Responsible communication of agricultural information means:','["being accurate and respectful", "exaggerating", "misleading", "hiding sources"]'::jsonb,0,'Responsibility builds trust.','original'),
('127.47.d.11.F',3,'Before posting about a farm practice online, you should:','["ignore sources", "verify the information", "guess", "copy rumors"]'::jsonb,1,'Verification prevents misinformation.','original'),
('127.47.d.12.A',3,'Tone for a scientific audience should be:','["joking", "slangy", "formal and precise", "vague"]'::jsonb,2,'Match the audience.','original'),
('127.47.d.12.A',3,'Presenting to young children calls for:','["complex charts", "jargon", "long reports", "simple language and examples"]'::jsonb,3,'Audience determines language.','original'),
('127.47.d.12.B',3,'Effective presentations have an introduction, body and:','["conclusion", "quiz", "footnote", "delay"]'::jsonb,0,'Structure helps audiences.','original'),
('127.47.d.12.B',3,'Practicing a presentation helps to:','["avoid questions", "improve timing and confidence", "lose time", "add errors"]'::jsonb,1,'Rehearsal helps.','original'),
('127.47.d.12.C',3,'Constructive critique of a presentation looks at structure and:','["lunch", "hair", "transitions", "shoes"]'::jsonb,2,'Transitions guide listeners.','original'),
('127.47.d.12.C',3,'Evidence in a presentation should be:','["hidden", "unrelated", "invented", "relevant and credible"]'::jsonb,3,'Evidence supports claims.','original'),
('127.47.d.13.A',3,'Evaluating an agricultural resource begins with checking the:','["author and publisher", "color", "page count", "font"]'::jsonb,0,'Credibility starts with source.','original'),
('127.47.d.13.A',3,'Peer-reviewed research is generally:','["unchecked", "more rigorously checked", "random", "less checked"]'::jsonb,1,'Review improves reliability.','original'),
('127.47.d.13.B',3,'A website funded by a company selling a product may be:','["unusable", "incorrect always", "biased toward that product", "perfectly neutral"]'::jsonb,2,'Funding can influence content.','original'),
('127.47.d.13.C',4,'Comparing several sources helps you to:','["ignore data", "avoid choosing", "guess", "make a well-informed decision"]'::jsonb,3,'Triangulation improves accuracy.','original'),
('127.47.d.13.C',4,'When two sources conflict, a professional should:','["check which is more credible", "ignore both", "pick randomly", "assume the longer one"]'::jsonb,0,'Credibility decides.','original'),
('127.47.d.13.D',4,'Defending a decision requires:','["random claims", "citing the evidence used", "emotion only", "silence"]'::jsonb,1,'Evidence backs decisions.','original'),
('127.47.d.13.D',4,'Explaining how a resource was evaluated shows:','["confusion", "secrecy", "transparent reasoning", "bias"]'::jsonb,2,'Transparency builds trust.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_6_v1'
from (values
